'use client';

import { useEffect, useId, useRef, useState, type CSSProperties, type ReactNode } from 'react';
import './integration-marquee.css';

export interface IntegrationMarqueeItem { id: string; label: string; logo: ReactNode; }
export interface IntegrationConnection { id: string; name: string; detail: string; logo: ReactNode; }
export interface IntegrationMarqueeProps {
  rows: IntegrationMarqueeItem[][];
  connections?: IntegrationConnection[];
  title?: ReactNode;
  durations?: number[];
  paused?: boolean;
  cycleConnections?: boolean;
  showControls?: boolean;
  className?: string;
}

/** Three seamless logo ribbons and an illustrative connection-status sequence. */
export function IntegrationMarquee({ rows, connections = [], title = 'Works with the tools you already use.', durations = [120,140,130], paused = false, cycleConnections = true, showControls = true, className = '' }: IntegrationMarqueeProps) {
  const uid = useId();
  const root = useRef<HTMLElement>(null);
  const [held, setHeld] = useState(false);
  const [environment, setEnvironment] = useState({ visible:false, hidden:false, reduced:false });
  const [copies,setCopies] = useState<number[]>([]);
  const [index, setIndex] = useState(0);
  const [phase, setPhase] = useState<'connecting'|'syncing'|'connected'>('connected');
  const running = environment.visible && !environment.hidden && !environment.reduced && !paused && !held;
  const connection = connections.length ? connections[index % connections.length] : undefined;
  useEffect(() => {
    const element = root.current;
    if (!element) return;
    const media = matchMedia('(prefers-reduced-motion: reduce)');
    let visible = typeof IntersectionObserver === 'undefined';
    const sync = () => setEnvironment({ visible, hidden:document.hidden, reduced:media.matches });
    const observer = typeof IntersectionObserver === 'undefined' ? null : new IntersectionObserver(([entry]) => { visible=entry.isIntersecting; sync(); });
    observer?.observe(element);
    media.addEventListener('change',sync);
    document.addEventListener('visibilitychange',sync);
    sync();
    return () => { observer?.disconnect(); media.removeEventListener('change',sync); document.removeEventListener('visibilitychange',sync); };
  },[]);
  useEffect(() => {
    const element=root.current;
    if (!element) return;
    const measure=()=>{
      const next=Array.from(element.querySelectorAll<HTMLElement>('.ac-integration-marquee__row')).map(row=>{
        const group=row.querySelector<HTMLElement>('.ac-integration-marquee__group');
        const width=group?.getBoundingClientRect().width??0;
        return width>0?Math.max(2,Math.min(128,Math.ceil(row.clientWidth/width)+1)):3;
      });
      setCopies(previous=>previous.length===next.length&&previous.every((count,index)=>count===next[index])?previous:next);
    };
    const observer=typeof ResizeObserver==='undefined'?null:new ResizeObserver(measure);
    observer?.observe(element);
    window.addEventListener('resize',measure);
    measure();
    return ()=>{observer?.disconnect();window.removeEventListener('resize',measure);};
  },[rows]);
  useEffect(() => {
    if (!running || !cycleConnections || connections.length < 2) return;
    const timer = window.setTimeout(() => {
      if (phase==='connected') { setIndex(value=>value+1); setPhase('connecting'); }
      else setPhase(phase==='connecting'?'syncing':'connected');
    },phase==='connected'?5000:1300);
    return () => window.clearTimeout(timer);
  },[running,cycleConnections,connections.length,index,phase]);
  const displayedPhase = environment.reduced || !cycleConnections ? 'connected' : phase;
  return <section ref={root} className={`ac-integration-marquee ${className}`.trim()} aria-labelledby={`${uid}-title`} data-running={running}>
    <div className="ac-integration-marquee__header">
      <h2 id={`${uid}-title`}>{title}</h2>
      {connection && <div className="ac-integration-marquee__connection" aria-label={`${connection.name}: ${displayedPhase}`}>
        <span className="ac-integration-marquee__connection-logo" key={connection.id} aria-hidden="true">{connection.logo}</span>
        <span className="ac-integration-marquee__connection-copy"><strong>{connection.name}</strong><span title={connection.detail}>{displayedPhase==='connecting'?'Signing in…':displayedPhase==='syncing'?'Syncing your workspace…':connection.detail}</span></span>
        <span className="ac-integration-marquee__status" data-connected={displayedPhase==='connected'}><svg viewBox="0 0 16 16" fill="none" aria-hidden="true">{displayedPhase==='connected'?<path d="m3 8 3 3 7-7"/>:<path className="ac-integration-marquee__spinner" d="M13 8a5 5 0 1 1-3-4.58"/>}</svg>{displayedPhase==='connected'?'Connected':displayedPhase==='syncing'?'Syncing':'Connecting'}</span>
      </div>}
    </div>
    <div className="ac-integration-marquee__rows">
      {rows.filter(row=>row.length>0).map((row,rowIndex)=><div className="ac-integration-marquee__row" key={rowIndex}>
        <div className="ac-integration-marquee__track" style={{'--ac-integration-copies':copies[rowIndex]??3,'--ac-integration-duration':`${Number.isFinite(durations[rowIndex])?Math.max(20,Math.min(300,durations[rowIndex])):120}s` } as CSSProperties} data-reverse={rowIndex%2===1}>
          {Array.from({length:copies[rowIndex]??3},(_,copy)=>copy).map(copy=><div className="ac-integration-marquee__group" key={copy} aria-hidden={copy>0?true:undefined} role={copy===0?'list':undefined} aria-label={copy===0?`Integration row ${rowIndex+1}`:undefined}>
            {row.map(item=><span className="ac-integration-marquee__tile" key={item.id} title={item.label} role={copy===0?'listitem':undefined}><span role={copy===0?'img':undefined} aria-label={copy===0?item.label:undefined}>{item.logo}</span></span>)}
          </div>)}
        </div>
      </div>)}
    </div>
    {showControls && <div className="ac-integration-marquee__controls"><button type="button" onClick={()=>setHeld(value=>!value)} disabled={paused||environment.reduced} aria-pressed={held||paused}>{environment.reduced?'Motion reduced':held||paused?'Play motion':'Pause motion'}</button></div>}
  </section>;
}

.ac-integration-marquee { --ac-integration-theme-surface:#fcfbff; --ac-integration-theme-ink:#181630; --ac-integration-theme-muted:#68647f; --ac-integration-theme-line:#e8e6ed; --ac-integration-theme-tile:#fff; container-type:inline-size; overflow:hidden; padding:64px 0 76px; background:var(--ac-integration-surface,var(--ac-integration-theme-surface)); color:var(--ac-integration-ink,var(--ac-integration-theme-ink)); font-family:var(--ac-integration-font,Geist,Arial,sans-serif); }
.ac-integration-marquee *, .ac-integration-marquee *::before, .ac-integration-marquee *::after { box-sizing:border-box; }
.ac-integration-marquee__header { display:grid; grid-template-columns:minmax(0,1fr) minmax(0,400px); align-items:end; gap:48px; width:100%; max-width:1200px; margin-inline:auto; padding-inline:32px; }
.ac-integration-marquee__header h2 { max-width:20ch; margin:0; font-size:64px; line-height:1; font-weight:500; letter-spacing:-.02em; text-wrap:balance; }
.ac-integration-marquee__connection { display:flex; align-items:center; gap:14px; min-width:0; margin-bottom:12px; padding:14px 16px; border:1px solid var(--ac-integration-line,var(--ac-integration-theme-line)); border-radius:20px; }
.ac-integration-marquee__connection-logo { display:grid; place-items:center; width:44px; height:44px; flex-shrink:0; border:1px solid var(--ac-integration-line,var(--ac-integration-theme-line)); border-radius:12px; background:var(--ac-integration-tile,var(--ac-integration-theme-tile)); animation:ac-integration-pop 350ms ease; }
.ac-integration-marquee__connection-logo > :is(svg,img) { display:block; width:23px; height:23px; object-fit:contain; }
.ac-integration-marquee__connection-copy { flex:1; min-width:0; }
.ac-integration-marquee__connection-copy strong { display:block; font-size:15px; line-height:1.25; font-weight:500; }
.ac-integration-marquee__connection-copy > span { display:block; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; margin-top:4px; color:var(--ac-integration-muted,var(--ac-integration-theme-muted)); font-size:13px; line-height:1.25; }
.ac-integration-marquee__status { display:inline-flex; flex-shrink:0; align-items:center; gap:6px; min-height:28px; padding:4px 10px; border-radius:999px; background:color-mix(in srgb,currentColor 5%,transparent); color:var(--ac-integration-muted,var(--ac-integration-theme-muted)); font-size:12.5px; line-height:1.25; font-weight:500; }
.ac-integration-marquee__status[data-connected='true'] { background:#e3f4ea; color:#087949; }
.ac-integration-marquee__status svg { width:14px; height:14px; stroke:currentColor; stroke-width:1.5; stroke-linecap:round; stroke-linejoin:round; }
.ac-integration-marquee__spinner { transform-origin:center; animation:ac-integration-spin 1s linear infinite; }
.ac-integration-marquee__rows { display:flex; flex-direction:column; gap:16px; margin-top:80px; }
.ac-integration-marquee__row { overflow:hidden; padding-block:4px; mask-image:linear-gradient(90deg,transparent,#000 14%,#000 86%,transparent); }
.ac-integration-marquee__track { display:flex; width:max-content; animation:ac-integration-slide var(--ac-integration-duration,120s) linear infinite; }
.ac-integration-marquee__track[data-reverse='true'] { animation-direction:reverse; }
.ac-integration-marquee__group { display:flex; align-items:center; gap:16px; flex-shrink:0; padding-right:16px; }
.ac-integration-marquee__tile { display:grid; place-items:center; flex-shrink:0; width:60px; height:60px; border-radius:18px; background:var(--ac-integration-tile,var(--ac-integration-theme-tile)); box-shadow:0 0 0 1px var(--ac-integration-line,var(--ac-integration-theme-line)),0 1px 2px #1413110a; }
.ac-integration-marquee__tile > span { display:grid; place-items:center; width:36px; height:36px; }
.ac-integration-marquee__tile :is(svg,img) { display:block; width:100%; height:100%; object-fit:contain; }
.ac-integration-marquee__controls { display:flex; justify-content:flex-end; max-width:1200px; margin:22px auto 0; padding-inline:32px; }
.ac-integration-marquee__controls button { min-height:36px; padding:4px 0; border:0; background:transparent; color:var(--ac-integration-muted,var(--ac-integration-theme-muted)); font:inherit; font-size:11px; line-height:1.4; cursor:pointer; text-underline-offset:4px; }
.ac-integration-marquee__controls button:hover:not(:disabled) { color:inherit; text-decoration:underline; }
.ac-integration-marquee__controls button:focus-visible { outline:2px solid currentColor; outline-offset:5px; }
.ac-integration-marquee__controls button:disabled { cursor:default; opacity:.65; }
.ac-integration-marquee[data-running='false'] :is(.ac-integration-marquee__track,.ac-integration-marquee__spinner) { animation-play-state:paused; }
@keyframes ac-integration-slide { to { transform:translateX(calc(-100% / var(--ac-integration-copies,3))); } }
@keyframes ac-integration-spin { to { transform:rotate(360deg); } }
@keyframes ac-integration-pop { from { opacity:.4; transform:scale(.9); } to { opacity:1; transform:scale(1); } }
@container (max-width:979px) { .ac-integration-marquee__header { grid-template-columns:1fr; gap:32px; } .ac-integration-marquee__header h2 { font-size:56px; } .ac-integration-marquee__connection { width:100%; max-width:400px; margin:0; } .ac-integration-marquee__rows { margin-top:56px; } }
@container (max-width:599px) { .ac-integration-marquee__header,.ac-integration-marquee__controls { padding-inline:20px; } .ac-integration-marquee__header h2 { font-size:44px; } .ac-integration-marquee__rows { gap:12px; } .ac-integration-marquee__group { gap:12px; padding-right:12px; } .ac-integration-marquee__tile { width:52px; height:52px; border-radius:16px; } .ac-integration-marquee__tile > span { width:30px; height:30px; } .ac-integration-marquee__connection { gap:10px; padding-inline:12px; } .ac-integration-marquee__status { font-size:11px; padding-inline:8px; } }
:where([data-theme='dark'],.dark) .ac-integration-marquee { --ac-integration-theme-surface:#1b1a22; --ac-integration-theme-ink:#f4f2fb; --ac-integration-theme-muted:#b6b1ca; --ac-integration-theme-line:#383541; --ac-integration-theme-tile:#fff; color-scheme:dark; }
@media (prefers-reduced-motion:reduce) { .ac-integration-marquee :is(.ac-integration-marquee__track,.ac-integration-marquee__spinner,.ac-integration-marquee__connection-logo) { animation:none; } }
